css:
.stamp-card {
  --paper: #fffdf5;
  --ink: #1a1a1a;
  --green: #00ff00;
  --shadow: #1a1a1a;

  display: inline-flex;
  align-items: center;
  gap: 1.2em;
  cursor: pointer;
  font-family:
    system-ui,
    -apple-system,
    sans-serif;
  user-select: none;
}

.stamp-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.stamp-paper {
  position: relative;
  width: 8em;
  height: 10em;
  background: var(--paper);
  border: 0.2em solid var(--ink);
  box-shadow: 0.4em 0.4em 0 0 var(--shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.8em;
  padding: 1em;
  transition:
    transform 0.15s ease,
    box-shadow 0.15s ease;
  overflow: hidden;
}

.stamp-card:hover .stamp-paper {
  transform: translateY(-0.2em) rotate(-1deg);
  box-shadow: 0.6em 0.6em 0 0 var(--shadow);
}

.stamp-card:active .stamp-paper {
  transform: translateY(0.2em) rotate(0deg);
  box-shadow: 0.1em 0.1em 0 0 var(--shadow);
}

.stamp-lines {
  display: flex;
  flex-direction: column;
  gap: 0.6em;
  width: 100%;
}

.line {
  width: 100%;
  height: 0.3em;
  background: var(--ink);
  border-radius: 0.1em;
  opacity: 0.15;
}

.line.short {
  width: 60%;
  margin: 0 auto;
}

.stamp-ink {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-15deg) scale(2.5);
  font-family: "Courier New", Courier, monospace;
  font-size: 1.4em;
  font-weight: 900;
  color: var(--green);
  border: 0.2em solid var(--green);
  padding: 0.2em 0.4em;
  border-radius: 0.2em;
  opacity: 0;
  pointer-events: none;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  box-shadow: inset 0 0 0 0.1em var(--green);
}

.stamp-input:checked ~ .stamp-paper .stamp-ink {
  animation: stamp-slam 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

.stamp-input:checked ~ .stamp-paper {
  transform: translateY(0.2em);
  box-shadow: 0.1em 0.1em 0 0 var(--shadow);
}

.stamp-label {
  font-size: 1em;
  font-weight: 800;
  color: var(--ink);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: transform 0.15s ease;
}

.stamp-card:hover .stamp-label {
  transform: translateX(0.2em);
}

.stamp-input:focus-visible ~ .stamp-paper {
  outline: 0.2em dashed var(--green);
  outline-offset: 0.4em;
}

@keyframes stamp-slam {
  0% {
    transform: translate(-50%, -50%) rotate(-25deg) scale(3);
    opacity: 0;
  }
  50% {
    transform: translate(-50%, -50%) rotate(-10deg) scale(0.9);
    opacity: 1;
  }
  75% {
    transform: translate(-50%, -50%) rotate(-15deg) scale(1.05);
    opacity: 1;
  }
  100% {
    transform: translate(-50%, -50%) rotate(-15deg) scale(1);
    opacity: 1;
  }
}
